using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using EchoSphere.Core;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class MenuArchiveBehaviorCheck {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");int n=0;void Check(bool ok,string why){n++;if(!ok)throw new Exception(why);}object Get(object o,string name)=>o.GetType().GetField(name,F).GetValue(o);void Set(object o,string name,object value)=>o.GetType().GetField(name,F).SetValue(o,value);object Call(object o,string name,params object[] args)=>o.GetType().GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);
 var owned=new HashSet<GameObject>();GameObject Make(string name){var g=new GameObject("Owned archive behavior "+name);owned.Add(g);return g;}var root=Make("runtime");root.SetActive(false);var r=root.AddComponent<EchoSphereRuntime>();r.enabled=false;root.SetActive(true);Set(r,"_knowledgeLoaded",true);Set(r,"_shopSaveLoaded",true);Set(r,"_shopSave",Activator.CreateInstance(r.GetType().GetNestedType("ShopSaveData",F)));Set(r,"_mainMenu",false);Set(r,"_tutorialStep",-1);Set(r,"_runEconomy",RunEconomyRules.Create(321));var player=Make("core");var core=player.AddComponent<PlayerCoreController2D>();Set(r,"_player",player.transform);Set(r,"_playerCore",core);var agents=(List<MonoBehaviour>)Get(r,"_simulationAgents");var enemies=(List<EnemyAgent2D>)Get(r,"_enemies");var known=(HashSet<string>)Get(r,"_knownKnowledgeIds");
 try{
  Set(r,"_wave",1);Call(r,"SpawnRegionalEnemy",false,null);var target=enemies.Last();int region=target.CampaignRegionStyle;string key=BestiaryCatalog.Key(region,target.IsBoss,target.IsElite,region==0?(string)target.GetType().GetProperty("SourceVisualVariant",F).GetValue(target):target.Role);Check(!known.Contains(key),"spawn is not a defeat");Call(r,"CollectRunKnowledge");Check(!known.Contains(key),"periodic observation cannot unlock enemy");target.ReceiveDamage(100000,emitFeedback:false);Check(known.Contains(key),"actual kill opens exact entry");var appearances=(Dictionary<string,BestiaryAppearance>)Get(r,"_bestiaryAppearances");Check(appearances[key].Role==target.Role&&appearances[key].Variant==(string)target.GetType().GetProperty("SourceVisualVariant",F).GetValue(target),"real appearance retained");int count=known.Count;Call(r,"RecordEnemyDefeat",target);Check(known.Count==count,"repeat defeat idempotent");
  Set(r,"_runTime",0f);Call(r,"RecordCompletedCharacterArchive");Check(!known.Contains("character:spherist"),"selection or zero length does not open character");Set(r,"_runTime",60f);foreach(var c in CharacterRules.All){Set(r,"_sphereCharacterId",c.Id);Call(r,"RecordCompletedCharacterArchive");Check(known.Contains("character:"+CharacterRules.ToSourceId(c.Id)),"completed character "+c.Id);}
  Set(r,"_knowledgeSection","monsters");var archive=(NativeArchiveScreen.State)Call(r,"ReadNativeArchiveState");Check(archive.Cards.Count==BestiaryCatalog.All.Count,"all enemies and bosses listed");Check(archive.Cards.Count(c=>c.Open)==1,"only killed entry open");Check(archive.Cards.All(c=>c.Enemy!=null),"real-render picture metadata for every enemy");Set(r,"_knowledgeSection","characters");archive=(NativeArchiveScreen.State)Call(r,"ReadNativeArchiveState");Check(archive.Cards.Count==10&&archive.Cards.All(c=>c.CharacterId!=null&&c.Details.Length>100&&c.DetailsEnglish.Length>100),"all character art and stories");
  Set(r,"_levelUp",true);Set(r,"_levelUpRerollsRemaining",1);Call(r,"BuildLevelUpChoices");Check((bool)Call(r,"RerollLevelUpChoices"),"one existing free reroll");Check((int)Get(r,"_levelUpRerollsRemaining")==0,"free reroll consumed once per run");uint rng=((SeededRng)Get(r,"_rng")).State;Check(!(bool)Call(r,"RerollLevelUpChoices"),"placeholder does not give reroll");Check(((SeededRng)Get(r,"_rng")).State==rng,"no hidden random draw after free reroll");
  var art=typeof(NativeArchiveScreen).Assembly.GetType("EchoSphere.Presentation.NativeArtifactIllustrations");Check((int)art.GetProperty("Count",F).GetValue(null)==90,"all90illustrations");var geometry=new HashSet<string>();foreach(var item in ArtifactRewardRules.Catalog(true)){string signature=(string)art.GetMethod("GeometryId",F).Invoke(null,new object[]{item.Id});Check(!string.IsNullOrEmpty(signature)&&geometry.Add(signature),"unique geometry composition "+item.Id);}
  var result=new{status="PASS",checks=n,bestiary=BestiaryCatalog.All.Count,artifacts=geometry.Count,scope="isolated actual Unity runtime: death-only unlock, exact killed anatomy, character completion, complete archive, free reroll and inert placeholder; no PlayerPrefs writes"};Directory.CreateDirectory("Library/menu-archive");File.WriteAllText("Library/menu-archive/behavior.json",Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
 }finally{foreach(var a in agents.ToArray())if(a!=null)owned.Add(a.gameObject);foreach(var g in owned.Where(g=>g!=null&&g!=root))UnityEngine.Object.DestroyImmediate(g);Set(r,"_mainMenu",true);UnityEngine.Object.DestroyImmediate(root);}
 }
}